import{_ as t,H as a,f as i,i as E}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"春节策划（二） | 给你推荐4本Web安全图书","description":"","frontmatter":{},"headers":[{"level":2,"title":"渗透测试书籍：《Ethical Hacking and Penetration Testing Guide》","slug":"渗透测试书籍-《ethical-hacking-and-penetration-testing-guide》","link":"#渗透测试书籍-《ethical-hacking-and-penetration-testing-guide》","children":[]},{"level":2,"title":"Web 应用攻防书籍：《黑客攻防技术宝典 Web 实战篇》和《白帽子讲 Web 安","slug":"web-应用攻防书籍-《黑客攻防技术宝典-web-实战篇》和《白帽子讲-web-安","link":"#web-应用攻防书籍-《黑客攻防技术宝典-web-实战篇》和《白帽子讲-web-安","children":[]},{"level":2,"title":"全》","slug":"全》","link":"#全》","children":[]},{"level":2,"title":"Web 应用安全书籍：《Web 之困：现代 Web 应用安全指南》","slug":"web-应用安全书籍-《web-之困-现代-web-应用安全指南》","link":"#web-应用安全书籍-《web-之困-现代-web-应用安全指南》","children":[]}],"relativePath":"Web漏洞挖掘实战/春节策划（二）｜给你推荐4本Web安全图书.md","filePath":"Web漏洞挖掘实战/春节策划（二）｜给你推荐4本Web安全图书.md","lastUpdated":1795536081000}'),n={name:"Web漏洞挖掘实战/春节策划（二）｜给你推荐4本Web安全图书.md"};function b(s,e,r,p,l,o){return a(),i("div",null,[...e[0]||(e[0]=[E('<h1 id="春节策划-二-给你推荐4本web安全图书" tabindex="-1">春节策划（二） | 给你推荐4本Web安全图书 <a class="header-anchor" href="#春节策划-二-给你推荐4本web安全图书" aria-label="Permalink to &quot;春节策划（二） | 给你推荐4本Web安全图书&quot;">​</a></h1><p>你好，我是王昊天。</p><p>新年伊始，相信你对自己的工作和生活有了新的期许。不知道在这个假期里，在陪伴家人之余，你准备用什么方式充实自己呢？</p><p>其实，在现在互联网知识爆炸的时代，学习资料是非常丰富的，从音频到视频，都极大地丰富了我们的学习手段，但读书依然是我给自己充电的重要方式。</p><p>虽然阅读书籍的场景在逐渐减少，但我还是会推荐你要拿出时间去读书。为什么呢？</p><p>因为其实读书有一些特殊优势的。一方面，读书可以让我们获得内心的平静，这种 inner-peace 是非常难得的。另一方面，来自书籍的知识会更加系统。虽然书籍上知识的即时性不足，但是书籍之所以能够成为书籍，就是因为其中的知识是更加底层的基础理论，是有深远价值的。所以，读书能够帮助我们更加系统和深入地了解完整的知识体系。</p><p>所以，为了帮助你更好地学习漏洞挖掘，我精心挑选了 4 本网络安全书籍分享给你，希望你可以从中找到自己感兴趣的书进行阅读。虽然这些书里有些例子在今天看来有些陈旧了，但是其中基础的原理和底层的方法依然是常看常新，可以经常为我处理新的漏洞带来灵感和启迪，也希望能对你有所帮助。</p><h2 id="渗透测试书籍-《ethical-hacking-and-penetration-testing-guide》" tabindex="-1">渗透测试书籍：《Ethical Hacking and Penetration Testing Guide》 <a class="header-anchor" href="#渗透测试书籍-《ethical-hacking-and-penetration-testing-guide》" aria-label="Permalink to &quot;渗透测试书籍：《Ethical Hacking and Penetration Testing Guide》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/1.png" alt=""></a></p><p>漏洞挖掘属于渗透测试的一部分。要想学好漏洞挖掘，我们首先要掌握渗透测试的基础知识。</p><p>与 Web 领域的渗透测试和漏洞挖掘相比，完整的渗透测试项目流程会更加复杂，涉及到目标发现、资产测绘、服务识别、漏洞分析、漏洞利用、远控免杀、横向移动等多方面知识。了解完整的渗透测试流程，有助于我们建立网络安全领域的全局观。</p><p>这本渗透测试书，非常方便理解，即使你是初学者也可以看懂。书中按照渗透测试的过程，通俗易懂地讲解了每个阶段需要用到的工具，以及不同阶段之间的联系，可以帮我们在漏洞挖掘领域打下坚实的基础。</p><p>所以，如果你是对渗透测试、网络攻防感兴趣的初级同学，这本优秀的入门级读物非常适合你。</p><h2 id="web-应用攻防书籍-《黑客攻防技术宝典-web-实战篇》和《白帽子讲-web-安" tabindex="-1">Web 应用攻防书籍：《黑客攻防技术宝典 Web 实战篇》和《白帽子讲 Web 安 <a class="header-anchor" href="#web-应用攻防书籍-《黑客攻防技术宝典-web-实战篇》和《白帽子讲-web-安" aria-label="Permalink to &quot;Web 应用攻防书籍：《黑客攻防技术宝典 Web 实战篇》和《白帽子讲 Web 安&quot;">​</a></h2><h2 id="全》" tabindex="-1">全》 <a class="header-anchor" href="#全》" aria-label="Permalink to &quot;全》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/2.png" alt=""></a></p><p>《黑客攻防技术宝典》这本书，结合了 Web 安全领域专家的经验，系统地阐述了如何针对Web 应用发起攻击与反攻击，同时深入剖析了攻击时所需要的步骤、技巧和工具。</p><p>这本书主要关注在 Web 安全实战领域，除了理论知识外，还包含了大量实战层面的攻击技巧和应对措施。此外，书中还有几百个漏洞实战，可以帮助你巩固所学内容。</p><p>所以，这本书非常适合掌握了一定 Web 渗透知识但缺乏大量实战经验的同学，是优秀的入门级提高读物。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/3.png" alt=""></a></p><p>《白帽子讲 Web 安全》这本书，会为你一一剖析各种 Web 漏洞的原理及攻防之道。它不仅仅有原理分析还有实践指导，是值得每一位 Web 安全从业者阅读的书。</p><p>这本书中详细列举了各种存在的攻防技术，及其技术的前世今生。其核心亮点是，深入浅出地讲解了 Web 安全领域的知识，并从技术底层和安全架构顶层的视角，带你深入构建完整的Web 安全理念。这样一来，就可以帮助你全面学习 Web 安全了。</p><p>所以，这本书非常适合掌握了一定 Web 安全知识，同时想要理解底层逻辑以进一步提高 Web安全认知的同学。这是一本优秀的提高级读物。</p><h2 id="web-应用安全书籍-《web-之困-现代-web-应用安全指南》" tabindex="-1">Web 应用安全书籍：《Web 之困：现代 Web 应用安全指南》 <a class="header-anchor" href="#web-应用安全书籍-《web-之困-现代-web-应用安全指南》" aria-label="Permalink to &quot;Web 应用安全书籍：《Web 之困：现代 Web 应用安全指南》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/4.png" alt=""></a></p><p>介绍完攻击角度的三本书之后，我再推荐一本安全防护角度的书籍《Web 之困：现代 Web 应用安全指南》。在 Web 安全领域，这本书被称为圣经。</p><p>有业内人士这样评价这本书：从 HTTP 协议层逐级拆解 Web 安全风险，奇技淫巧、脑洞大开，其中外部资源调用 403 的钓鱼、打开新窗口重定向父页面的钓鱼、复杂协议的安全边界，在出版后的 4 年里依然风靡，实在佩服！</p><p>它会带着你深入剖析现代 Web 浏览器的技术原理、安全机制和设计上的安全缺陷，为你提供基于浏览器的安全隐患，例如浏览器缓存、浏览器内存的密码、浏览器历史记录等的保护措施。</p><p>好了，上面这 4 本书，就是我为你精选的 Web 安全的阅读书单了。</p><p>每一个项目都有终点，但在自我精进的道路上，我们仍需步履不停。今天我推荐的这些书目，你可以利用假期时间潜心阅读，掌握它们的核心内容，理解其中的思维方法。希望在新的一年里，这些知识成果不仅能帮助带你实现技术上的飞跃，更能拓展你的知识边界，带你实现自我成长。</p><p>好了，今天的分享就到这里，如果你有其它好书推荐，也欢迎在评论区留言，我们下节课再见。</p>',31)])])}const c=t(n,[["render",b]]);export{g as __pageData,c as default};
